<script setup lang="ts">
import { useForm } from '@inertiajs/vue3';import { ref, watch, onUnmounted, computed } from 'vue';
import type { Device,Observation } from '../types';import AppModal from './AppModal.vue';import FormErrors from './FormErrors.vue';import StatusBadge from './StatusBadge.vue';
const props=defineProps<{open:boolean;devices:Device[];date:string;today:string;record:Observation|null;canWrite:boolean;ticketConfigured:boolean}>();const emit=defineEmits<{close:[]}>();
const form=useForm({device_ids:[] as number[],date:'',update_status:false,attach_images:false,create_ticket:false,status:'online',notes:'',ticket_title:'',images:[] as File[],remove_attachment_ids:[] as number[]});
const urls=ref<string[]>([]),captureBusy=ref(false),captureError=ref('');let generation=0;const input=ref<HTMLInputElement|null>(null);const bulk=computed(()=>props.devices.length>1);
const editable=computed(()=>props.canWrite&&props.date===props.today);
const retained=computed(()=>props.record?.attachments.filter(a=>!form.remove_attachment_ids.includes(a.id))||[]);
function revoke(){urls.value.forEach(URL.revokeObjectURL);urls.value=[];}
watch(()=>props.open,open=>{generation++;revoke();if(!open)return;form.reset();form.clearErrors();captureError.value='';form.device_ids=props.devices.map(d=>d.id);form.date=props.date;form.status=['online','offline'].includes(props.record?.status||'')?props.record!.status!:'online';form.notes=props.record?.notes||'';form.ticket_title=`${props.devices[0]?.name||'Camera'} - support request`;if(bulk.value&&editable.value)form.update_status=true;});
onUnmounted(()=>{generation++;revoke();});
function upload(files:File[]){if(!editable.value)return;if(retained.value.length+form.images.length+files.length>6){captureError.value='Up to six images per record.';return;}if(files.some(f=>!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>8*1024*1024)){captureError.value='Use PNG, JPEG or WebP files up to 8 MB each.';return;}form.images.push(...files);urls.value.push(...files.map(f=>URL.createObjectURL(f)));captureError.value='';}
function remove(index:number){URL.revokeObjectURL(urls.value[index]);urls.value.splice(index,1);form.images.splice(index,1);}
async function capture(){if(!editable.value)return;if(!navigator.mediaDevices?.getDisplayMedia){captureError.value='Capture requires HTTPS or localhost and a supported browser. You can upload an image instead.';return;}const token=generation;let stream:MediaStream|undefined;captureBusy.value=true;try{stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const video=document.createElement('video');video.srcObject=stream;video.muted=true;await video.play();const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d')?.drawImage(video,0,0);const blob=await new Promise<Blob|null>(r=>canvas.toBlob(r,'image/jpeg',.85));if(blob&&token===generation)upload([new File([blob],`capture-${Date.now()}.jpg`,{type:'image/jpeg'})]);}catch{if(token===generation)captureError.value='Capture cancelled or unavailable. Upload or paste an image instead.';}finally{stream?.getTracks().forEach(t=>t.stop());captureBusy.value=false;}}
function paste(e:ClipboardEvent){if(!form.attach_images||!editable.value)return;const files=Array.from(e.clipboardData?.files||[]).filter(f=>f.type.startsWith('image/'));if(files.length){e.preventDefault();upload(files);}}
function save(){if(!editable.value)return;form.post('/observations',{forceFormData:true,preserveScroll:true,onSuccess:()=>emit('close')});}
const hasActions=computed(()=>form.update_status||form.attach_images||form.create_ticket);
</script>
<template><AppModal :open="open" :title="bulk?`Update ${devices.length} cameras`:`${devices[0]?.asset_id||''} · ${devices[0]?.name||''}`" :busy="form.processing||captureBusy" @close="emit('close')"><form @submit.prevent="save" @paste="paste"><p>{{date}} · {{bulk?'One observation will be recorded for every selected camera.':devices[0]?.branch.name}}</p><FormErrors :errors="form.errors"/><p v-if="date!==today" class="rw-note" role="status"><strong>Past record ? read-only.</strong> Status updates, image changes, and ticket creation are only available for today (Philippine time).</p><fieldset v-if="editable" :disabled="form.processing"><legend>1. Select actions</legend><p>Choose one or more actions, then save them together.</p><div class="rw-action-choices"><label><input v-model="form.update_status" type="checkbox">Update status</label><label v-if="!bulk"><input v-model="form.attach_images" type="checkbox">Attach images</label><label v-if="!bulk"><input v-model="form.create_ticket" type="checkbox">Create ticket</label></div><ul v-if="bulk" class="rw-selection-list"><li v-for="d in devices" :key="d.id">{{d.asset_id}} · {{d.name}}</li></ul><label v-if="form.update_status">Camera status<select v-model="form.status"><option value="online">Online</option><option value="offline">Offline</option></select></label><section v-if="form.attach_images"><h3>Screenshot evidence</h3><p>Capture a camera window, paste images, or upload up to six images (8 MB each).</p><div class="rw-inline-actions"><button type="button" class="rw-btn" :disabled="captureBusy" @click="capture">{{captureBusy?'Capturing…':'Capture screenshot'}}</button><button type="button" class="rw-btn" @click="input?.click()">Upload images</button><input ref="input" hidden type="file" multiple accept="image/jpeg,image/png,image/webp" @change="upload(Array.from(($event.target as HTMLInputElement).files||[]));($event.target as HTMLInputElement).value='' "></div><p v-if="captureError" class="rw-errors" role="alert">{{captureError}}</p><div class="rw-gallery compact"><article v-for="a in retained" :key="a.id"><img :src="a.url" :alt="a.name"><button type="button" class="rw-link" @click="form.remove_attachment_ids.push(a.id)">Remove saved image</button></article><article v-for="(url,index) in urls" :key="url"><img :src="url" :alt="`New image ${index+1}`"><button type="button" class="rw-link" @click="remove(index)">Remove image {{index+1}}</button></article></div></section><section v-if="form.create_ticket"><h3>External ticket</h3><template v-if="record?.ticket"><StatusBadge :status="record.ticket.status"/><p>{{record.ticket.title}}</p><p v-if="record.ticket.error" class="rw-errors">{{record.ticket.error}}</p><a v-if="record.ticket.external_url" :href="record.ticket.external_url" target="_blank" rel="noopener noreferrer">Open external ticket {{record.ticket.external_id}}</a><p v-else>Saving will retry this request if it is not already queued or processing.</p></template><label>Ticket title<input v-model="form.ticket_title" maxlength="180" required></label><p class="rw-note">{{ticketConfigured?'Creation is handled by the external provider in the background. The ticket indicator appears after confirmation.':'The ticket provider is not connected yet. Your record and request will be saved; a ticket will not be reported as created.'}}</p></section><label v-if="hasActions">Observation / action taken *<textarea v-model="form.notes" required maxlength="4000" placeholder="Describe what you checked and what you found."></textarea></label></fieldset><section v-if="(!editable||!hasActions)&&record"><h3>Saved daily record</h3><StatusBadge :status="record.status"/><p>{{record.notes||'No notes.'}}</p><div v-if="record.ticket"><StatusBadge :status="record.ticket.status"/><p>{{record.ticket.title}}</p><a v-if="record.ticket.external_url" :href="record.ticket.external_url" target="_blank" rel="noopener noreferrer">Open external ticket {{record.ticket.external_id}}</a></div><p v-if="record.checked_at">Checked by {{record.checker}} · {{new Date(record.checked_at).toLocaleString()}}</p><div class="rw-gallery compact"><a v-for="a in record.attachments" :key="a.id" :href="a.url" target="_blank" rel="noopener noreferrer"><img :src="a.url" :alt="a.name"></a></div></section><p v-if="!editable&&!record" class="rw-note">No observation was saved for this date.</p><p v-if="!canWrite" class="rw-note">Your role has read-only access.</p><div class="rw-form-actions"><button type="button" class="rw-btn" :disabled="form.processing||captureBusy" @click="emit('close')">{{editable?'Cancel':'Close'}}</button><button v-if="editable" class="rw-btn primary" :disabled="!hasActions||form.processing||captureBusy">{{form.processing?'Saving…':'Save selected actions'}}</button></div><p v-if="form.progress">Uploading {{form.progress.percentage}}%</p></form></AppModal></template>
